// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" kullan;
"src/models/product.hudhud" kullan;
"src/models/order.hudhud" kullan;

// Servisleri içe aktar
"src/services/auth.hudhud" kullan;
"src/services/payment.hudhud" kullan;
"src/services/notification.hudhud" kullan;

// Yardımcı sınıfları içe aktar
"src/utils/validation.hudhud" kullan;
"src/utils/formatting.hudhud" kullan;

yaz("============================================================");
yaz("E-Ticaret Sistemi - Modüler Mimari Demo");
yaz("============================================================\n");

// Servis örnekleri oluştur
değişken authService = yeni AuthService();
değişken paymentService = yeni PaymentService();
değişken notificationService = yeni NotificationService();

yaz("1️⃣  KULLANICI KAYDI");
yaz("─────────────────────────────────────────────────────────\n");

// Yeni kullanıcı oluştur
değişken newUser = yeni User("Davut Süleyman", "davut@example.com", "güvenli123");
yaz("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email doğrula
eğer (Validation.email(newUser.email)) {
    yaz("✓ Email geçerli: " + newUser.email);
} değilse {
    yaz("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
değişken authResult = authService.register(newUser);
eğer (authResult.success) {
    yaz("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

yaz("\n2️⃣  ÜRÜN OLUŞTURMA");
yaz("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
değişken product = yeni Product("MacBook Pro M3", 45000, 10, "Elektronik");
yaz("Ürün oluşturuldu: " + product.bilgi());

// Fiyat doğrula
eğer (Validation.price(product.price)) {
    yaz("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
eğer (product.inStock()) {
    yaz("✓ Ürün stokta mevcut");
} değilse {
    yaz("✗ Ürün stokta yok");
}

yaz("\n3️⃣  SİPARİŞ OLUŞTURMA");
yaz("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
değişken order = yeni Order(
    newUser.id,
    product.id,
    1,
    product.price
);
yaz("Sipariş oluşturuldu: " + order.bilgi());

yaz("\n4️⃣  ÖDEME İŞLEMİ");
yaz("─────────────────────────────────────────────────────────\n");

// Ödeme işle
değişken paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

eğer (paymentResult.success) {
    yaz("✓ " + paymentResult.message);
    yaz("  İşlem No: " + paymentResult.transactionId);
    yaz("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    yaz("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    yaz("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} değilse {
    yaz("✗ Ödeme başarısız: " + paymentResult.error);
}

yaz("\n============================================================");
yaz("✓ E-Ticaret sistemi demo tamamlandı!");
yaz("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
yaz("============================================================");

