// Payment Service - Ödeme Servisi

sınıf PaymentService {
    işlev process(orderId, amount, method) {
        // Basitleştirilmiş ödeme işlemi
        değişken success = doğru; // Gerçekte API çağrısı yapılır

        eğer (success) {
            dön {
                success: doğru,
                transactionId: "TXN_" + Math.floor(Math.random() * 100000),
                amount: amount,
                method: method,
                message: "Ödeme başarılı"
            };
        } değilse {
            dön {
                success: yanlış,
                error: "Ödeme başarısız"
            };
        }
    }

    işlev refund(transactionId) {
        dön {
            success: doğru,
            refundId: "REF_" + Math.floor(Math.random() * 100000)
        };
    }
}

