// Validation Utilities - Doğrulama Fonksiyonları

sınıf Validation {
    statik işlev email(email) {
        // Basit email doğrulama
        dön email.length > 5;
    }

    statik işlev password(password) {
        // Şifre en az 6 karakter olmalı
        dön password.length >= 6;
    }

    statik işlev price(price) {
        dön price > 0;
    }

    statik işlev phone(phone) {
        // Telefon numarası doğrulama
        dön phone.length == 10;
    }

    statik işlev required(value) {
        dön value.length > 0;
    }
}

