// Formatting Utilities - Formatlama Fonksiyonları

sınıf Formatting {
    statik işlev currency(amount, currency) {
        eğer (currency == "TRY") {
            dön amount + " ₺";
        } değilse {
            eğer (currency == "USD") {
                dön "$" + amount;
            } değilse {
                eğer (currency == "EUR") {
                    dön "€" + amount;
                } değilse {
                    dön amount + " " + currency;
                }
            }
        }
    }

    statik işlev date(date) {
        dön date;
    }

    statik işlev phone(phone) {
        // (555) 123-4567 formatı
        dön "(" + phone + ")";
    }

    statik işlev number(num) {
        // 1,234,567 formatı
        dön num;
    }
}

